INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('DILLARD''S x STATEMENT SERIES PRE-EVENT FASHION MIXER', 'SVPERDVPERFLY', 'General Networking', 'The Statement Series is not your typical networking event; it’s a creative and immersive experience designed for both seasoned industry', 'The Statement Series is not your typical networking event; it’s a creative and immersive experience designed for both seasoned industry professionals and emerging talents. Through thoughtfully curated activations and collaborative opportunities, the Statement Series empowers creatives to express themselves boldly, connect meaningfully, and grow purposefully. KICKOFF: Saturday October 24th Hosted at Dillard''s Florida Mall from 6pm-8pm. Music, refreshments and light bites. 🔸🔸🔸 If you haven''t grabbed your MAIN EVENT: Sunday October 25th Statement Series ticket yet, go directly through our website : www.statementseries.com 🔸🔸🔸 Whether you’re a designer, model, stylist, photographer, or simply passionate about the world of fashion, this event is your space to be seen, heard, and inspired. The 2026 Theme is "Sustain & Scale" , which is an invitation to embrace quality and responsible More info', '2026-10-24T22:00:00Z', 'Dillard''s', '8001 South Orange Blossom Trail, Orlando, FL 32809', 'Orlando', 'FL', '32809', 28.4464838, -81.3924487, 'SVPERDVPERFLY', 0, false, 'Paid (see event page)', 'live', 'eventbrite', 'https://www.eventbrite.com/e/dillards-x-statement-series-pre-event-fashion-mixer-tickets-1996534050089', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
