INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Let''s Connect! Realtors Networking Mixer for Entrepreneurs & Professionals', 'Greater Haitian American Chamber of Commerce', 'Real Estate Meetings', 'The Greater Haitian American Chamber of Commerce Orlando is excited to host a vibrant event that unites the city’s leaders, entrepreneurs,', 'The Greater Haitian American Chamber of Commerce Orlando is excited to host a vibrant event that unites the city’s leaders, entrepreneurs, and professionals. Join us for an evening that fosters a lively social atmosphere where meaningful connections and valuable networking opportunities can flourish. This event is open to all professionals eager to engage with like-minded individuals who share a passion for personal and professional growth. Whether you’re looking to expand your network, seek mentorship, or simply make new friends, this is the ideal gathering for you! Don’t miss this chance to be part of Orlando’s dynamic young professional community. Save the date, and get ready to forge connections, share experiences, and collaborate toward a brighter future together. Please note: All sales are final; there are no refunds. More info: https://www.eventbrite.com/e/lets-connect-realtors-ne', '2026-11-19T23:00:00Z', 'Centric Realty Services, LLC.', '1412 West Colonial Drive, ##200, Orlando, FL 32804', 'Orlando', 'FL', '32804', 28.5527382, -81.40006749999999, 'Greater Haitian American Chamber of Commerce', 0, false, 'Paid (see event page)', 'live', 'eventbrite', 'https://www.eventbrite.com/e/lets-connect-realtors-networking-mixer-for-entrepreneurs-professionals-tickets-1982252726265', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Networking Pizza Presents: "Hispanic Heritage Month"', 'Networking Pizza', 'General Networking', 'Celebrate Hispanic Heritage Month with Networking Pizza on October 18 from 1–4 PM at the Orlando Public Library for an afternoon centered', 'Celebrate Hispanic Heritage Month with Networking Pizza on October 18 from 1–4 PM at the Orlando Public Library for an afternoon centered on connection, community, and meaningful conversation. We’re honored to welcome Karla Soto for an elevated discussion on Hispanic Women in Leadership —exploring the experiences, strengths, challenges, and opportunities facing Hispanic women in our community. Together, we’ll talk about how we can better support, champion, and create space for Hispanic women to lead and thrive, while sharing valuable resources and building stronger connections across our community. And, of course, it wouldn’t be Networking Pizza without pizza! Come ready to learn, connect, ask questions, and be part of an important conversation as we celebrate Hispanic Heritage Month together. Come for the conversation. Stay for the connection. Leave with new perspectives, resources, Mor', '2026-10-18T17:00:00Z', 'Orlando Public Library', '101 East Central Boulevard, Orlando, FL 32801', 'Orlando', 'FL', '32801', 28.5424041, -81.37661419999999, 'Networking Pizza', 0, false, '$10+', 'live', 'eventbrite', 'https://www.eventbrite.com/e/networking-pizza-presents-hispanic-heritage-month-tickets-1998656090168', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
