INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('BNI Momentum Orlando | Weekly Business Networking & Referral Meeting', 'Planwise Partners', 'General Networking', 'Looking to grow your business through stronger professional relationships and quality referrals? Come experience BNI Momentum. BNI Momentum', 'Looking to grow your business through stronger professional relationships and quality referrals? Come experience BNI Momentum. BNI Momentum is a professional referral networking chapter serving Orlando, Lake Nona, and the surrounding Central Florida business community . We bring together business owners, entrepreneurs, sales professionals, and other trusted professionals who believe that strong relationships create stronger business opportunities. Our weekly meetings are designed to help members and visitors build meaningful connections, understand each other’s businesses, exchange referrals, collaborate, and create opportunities for long-term growth. During the meeting, you can expect structured networking, member introductions, referral opportunities, a featured business presentation, relationship-building, and the opportunity to connect with trusted local professionals. Visitors are M', '2026-10-13T12:00:00Z', 'Curious Cork Kitchen & Bar', '14383 Narcoossee Road, Orlando, FL 32832', 'Orlando', 'FL', '14383', 28.3603777, -81.2428422, 'Planwise Partners', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/bni-momentum-orlando-weekly-business-networking-referral-meeting-tickets-2002106152397', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Calls & Coffee with Corinne Defilippis', 'The Alliance Home Group', 'General Networking', 'Ready to turn cold calls and follow-ups into closed deals? Join us for an exclusive in-person training designed specifically for real', 'Ready to turn cold calls and follow-ups into closed deals? Join us for an exclusive in-person training designed specifically for real estate agents looking to master phone prospecting, refine their scripts, and scale their production. Learn proven, high-converting strategies in a dynamic atmosphere while enjoying a fresh cup of coffee ☕. 🗓️ Date: October 13 ⏰ Time: 01:00pm 📍 Location: 11 S. Bumby Ave, Orlando, FL 32803 🎟️ Admission: Free / Limited Seats Available 👉 Reserve your spot today by replying to this post or sending us a DM! #OrlandoRealEstate #CallsAndCoffee #RealEstateAgentTraining #OrlandoRealtors #RealEstateProspecting #CorinneDefilippis More info: https://www.eventbrite.com/e/calls-coffee-with-corinne-defilippis-tickets-2002571086026', '2026-10-13T17:00:00Z', 'Alliance Culture Center', '11 s bumby ave, Orlando, FL Ready to turn cold calls and follow-ups into close', 'Orlando', 'FL', '', 28.506882, -81.352231, 'The Alliance Home Group', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/calls-coffee-with-corinne-defilippis-tickets-2002571086026', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Connections that Matter | Professional Networking Orlando', 'Fusion Academy Orlando', 'General Networking', 'Meet the professionals helping Central Florida students and families thrive. Join Fusion Academy Orlando for Connections That Matter, a', 'Meet the professionals helping Central Florida students and families thrive. Join Fusion Academy Orlando for Connections That Matter, a complimentary evening bringing together therapists, psychologists, educational consultants, school counselors, and other professionals who support school-age students. Connect with colleagues, exchange community resources, and build relationships over light bites, cocktails, and nonalcoholic beverages. Meet the Fusion Academy Orlando team and learn about our personalized, one-to-one education for students in grades 5–12. Coming with a colleague? We’d love to welcome them—please reserve a spot for each guest. Space is limited, and RSVP is required. More info: https://www.eventbrite.com/e/connections-that-matter-professional-networking-orlando-tickets-2002890744132', '2026-10-22T22:00:00Z', 'Eola View', '150 East Central Boulevard, Third Floor, Orlando, FL 32801', 'Orlando', 'FL', '32801', 28.5419424, -81.3764492, 'Fusion Academy Orlando', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/connections-that-matter-professional-networking-orlando-tickets-2002890744132', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Content & Connections with Sabrina', 'Eventbrite Organizer', 'General Networking', 'This isn''t your typical networking event. Content & Connections with Sabrina is bringing Orlando''s creative community together for an', 'This isn''t your typical networking event. Content & Connections with Sabrina is bringing Orlando''s creative community together for an afternoon of content, genuine connections, and good vibes. This isn''t a conference or a sit-down networking event. Come grab a drink, meet new faces, capture content, and connect with like-minded creatives. What to Expect: Curated content moments & photo opportunities Content Creation Tips & Creative Insights 15-minute speed networking session Food & drinks DJ & good vibes Opportunities to connect & collaborate Plenty of time to mix, mingle, and create Whether you''re a content creator, influencer, photographer, videographer, entrepreneur, or simply looking to expand your circle, C&C is where creativity meets connection. More info: https://www.eventbrite.com/e/content-connections-with-sabrina-tickets-2003307241888', '2026-11-07T19:00:00Z', '1720 N Goldenrod Rd', '1720 North Goldenrod Road, Orlando, FL 32807', 'Orlando', 'FL', '32807', 28.5707688, -81.286852, 'Eventbrite Organizer', 0, false, '$13.32+', 'live', 'eventbrite', 'https://www.eventbrite.com/e/content-connections-with-sabrina-tickets-2003307241888', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Coworking Mondays: Work, Connect, and Grow in Orlando', 'Pipeline Workspaces', 'General Networking', 'Join us at Pipeline Orlando every first Monday of the month for a coworking day! Work alongside other professionals, network, and boost', 'Join us at Pipeline Orlando every first Monday of the month for a coworking day! Work alongside other professionals, network, and boost your productivity in a vibrant workspace. Experience a productive and collaborative workday at Pipeline''s Coworking Mondays. Every first Monday of the month, from 9:00 AM to 5:00 PM, enjoy: Access to our shared workspace: A dynamic and inspiring environment to get your work done. Networking opportunities: Connect with fellow professionals, business owners, and entrepreneurs. High-speed, reliable internet: Stay connected and productive throughout the day. Kitchen access: Complimentary coffee and tea to keep you energized. Private phone booths: Conduct calls and meetings in peace and quiet. Convenient parking: Paid parking is available nearby for your convenience. Don''t miss this chance to experience Pipeline''s vibrant coworking community. Limited spots Mo', '2026-11-02T14:00:00Z', 'Pipeline Orlando Coworking and Shared Offices', '20 North Orange Avenue, #Suite 1100, Orlando, FL 32801', 'Orlando', 'FL', '32801', 28.5424194, -81.37945549999999, 'Pipeline Workspaces', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/coworking-mondays-work-connect-and-grow-in-orlando-tickets-1980639689629', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Downtown at Debonair — October Networking Edition', 'Fluent Mortgage', 'General Networking', 'ABOUT THIS EVENT Great relationships help great businesses grow. Join Fluent Mortgage And The Debonair Supper Club on Wednesday, October', 'ABOUT THIS EVENT Great relationships help great businesses grow. Join Fluent Mortgage And The Debonair Supper Club on Wednesday, October 21, for Downtown at Debonair — October Networking Edition. This networking event brings together real estate professionals, business owners, entrepreneurs, and professionals from across Orlando for an afternoon of conversation and connection. Introduce yourself, share what you do, and meet people whose experience, services, or ideas could complement your business. Whether you’re an established professional or expanding your local network, you’re welcome to join us. WHO SHOULD ATTEND • Real estate agents, brokers, and mortgage professionals • Builders, developers, and real estate investors • Business owners and entrepreneurs • Attorneys, insurance professionals, and local service providers • Business professionals looking to expand their network WHAT TO ', '2026-10-21T20:00:00Z', 'Debonair Supper Club', '183 South Orange Avenue, Orlando, FL 32801', 'Orlando', 'FL', '32801', 28.5405289, -81.3787863, 'Fluent Mortgage', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/downtown-at-debonair-october-networking-edition-tickets-2003109742161', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Free Rockstar Connect MK Alliance Networking Event (October, Orlando, FL)', 'Rockstar Connect', 'General Networking', 'Free MK Alliance Networking Event (October 27) Looking for a FREE networking event in Orlando, FL? Join us Tuesday, October 27, from 6–8 PM', 'Free MK Alliance Networking Event (October 27) Looking for a FREE networking event in Orlando, FL? Join us Tuesday, October 27, from 6–8 PM at Bar Louie (Orlando Gateway) for an evening of authentic business networking, new connections, and community. DATE: Tuesday, October 27, 2026 TIME: 6–8 PM LOCATION: Bar Louie (Orlando Gateway) COST: FREE RSVP NOW and reserve your FREE ticket. Hosted by MK Roundtable, MK Alliance Networking powered by Rockstar Connect brings together entrepreneurs, business owners, professionals, and local community members in a relaxed environment where genuine conversations can lead to meaningful relationships. If you live or work in Orlando, Kissimmee, Lake Nona, Winter Park, Lake Mary, Sanford, Altamonte Springs, or anywhere in the Greater Orlando area, come meet new people and expand your local network. This is not a traditional networking event with rigid More', '2026-10-27T22:00:00Z', 'Bar Louie - Orlando Gateway', '7015 South Semoran Boulevard, Orlando, FL 32822', 'Orlando', 'FL', '32822', 28.4620489, -81.3088329, 'Rockstar Connect', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/free-rockstar-connect-mk-alliance-networking-event-october-orlando-fl-tickets-2002664960808', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Gateway Connections Networking Event', 'Heidi Vold', 'General Networking', 'Build Stronger Business Networking Connections with the Gateway Connections! Join us in person to Network and boost your business luck with', 'Build Stronger Business Networking Connections with the Gateway Connections! Join us in person to Network and boost your business luck with some amazing business connections! Join us in person for an exciting Networking event: Business Visitor Day with the Gateway Connections Networking Group on Thursdays from 9-10:30am at Vanessa''s Coffee Shop 1331 Osceola Pkway, Kissimee, FL 34744 . This is your chance to connect, learn, and boost your business vibes and Networking connections with like-minded folks. Don’t miss out on fun networking, great insights, and a fresh take on creating opportunities. Bring your energy and get ready to make your own luck! Whether you''re a seasoned entrepreneur or a driven professional looking to grow your business, this open invitation is your opportuity to experience the power of intentional networking in Central Florida! Think about it: How would your More in', '2026-10-15T13:00:00Z', 'Vanessa''s Coffee Shop', '1331 Osceola Parkway, Kissimmee, FL 34744', 'Kissimmee', 'FL', '34744', 28.3427642, -81.3895485, 'Heidi Vold', 0, false, 'Free', 'live', 'eventbrite', 'https://www.eventbrite.com/e/gateway-connections-networking-event-tickets-1997912561253', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('HealthX Orlando Nursing Job Fair & Hiring Event for Employers', 'HealthX', 'Business Networking', 'The Format In a competitive healthcare market, top talent is rarely active on public job boards. We provide access to a pre-vetted pool of', 'The Format In a competitive healthcare market, top talent is rarely active on public job boards. We provide access to a pre-vetted pool of professionals in a format designed for speed and impact. Invite-Only: Every attendee is reviewed to ensure they hold valid credentials and relevant experience. Accelerated Interviews: Our "speed-dating" format allows you to conduct intro interviews with dozens of qualified candidates in a single session—volume that would typically require weeks of scheduling. Active Talent: Engage with 100+ motivated professionals who are actively seeking new opportunities. Candidates To ensure you can maximize your time, we provide complete transparency regarding who is in the room. Participating employers receive: Full Candidate Roster: Names and background details provided in advance. Professional Profiles: Direct links to LinkedIn or professional bios. More info: ', '2026-12-01T23:00:00Z', 'Orlando', 'Job Fair, Orlando, FL', 'Orlando', 'FL', '', 28.5383832, -81.3789269, 'HealthX', 0, false, '$495+', 'live', 'eventbrite', 'https://www.eventbrite.com/e/healthx-orlando-nursing-job-fair-hiring-event-for-employers-tickets-2002585392818', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
